-- OD015M3 / 6b aprovada. Somente odonto-qa pelo runner com host validado.
-- NAO executado pelo Dev. INSERTs de rodada abortam se o cleanup anterior nao terminou.
-- RESIDUO PERMANENTE INTENCIONAL: paciente e0150000-0000-4000-8000-000000000001, ficha ES e0150000-0000-4000-8000-000000000104,
-- evento ES e0150000-0000-4000-8000-000000000303, assinatura ES e0150000-0000-4000-8000-000000000801. Nunca apagar/contornar gatilho.
-- Paths ficticios: nao cria arquivos reais no storage. EXO/paciente_documentos e0150000-0000-4000-8000-000000000902
-- e metadado ficticio preservado pelo cleanup, que nao apaga o paciente nem seu acervo.
begin;

do $es$
begin
 if not exists(select 1 from public.pacientes p join public.fichas f on f.paciente_id=p.id
   join public.odontograma_eventos e on e.ficha_id=f.id join public.assinaturas a on a.id=e.assinatura_id
   where p.id='e0150000-0000-4000-8000-000000000001' and p.nome='Paciente Exclusao QA' and p.clinica_id='b0000000-0000-4000-8000-000000000001'
     and f.id='e0150000-0000-4000-8000-000000000104' and f.clinica_id=p.clinica_id and f.dentista_id='b0000000-0000-4000-8000-0000000000a1'
     and e.id='e0150000-0000-4000-8000-000000000303' and e.status='realizado' and e.assinatura_id='e0150000-0000-4000-8000-000000000801'
     and a.ficha_id=f.id and a.tipo='procedimentos')
   or (select count(*) from public.odontograma_eventos where ficha_id='e0150000-0000-4000-8000-000000000104')<>1 then
   raise exception 'fixture_es_estado_inesperado';
 end if;
end;
$es$;
commit;
